insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('e_carottes_rapees', 'Carottes râpées citron et cumin', 10, 4, null, 'entree', '{"toutes"}', '{}', false, false, '{"Épluche les carottes et râpe-les avec la grille fine.","Dans le saladier, mélange le jus du citron, l''huile, le cumin, sel et poivre.","Ajoute les carottes, mélange bien et parsème de persil ciselé. Laisse reposer 10 min au frais si tu peux : elles s''imprègnent de la sauce."}');
