insert into public.recipe_ingredients (recipe_id, position, ingredient_id, extra_ingredient_ids, label, qty, unit) values ('e_carottes_rapees', 5, 'herbes_epices', '{}', 'persil', null, null);
insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('e_concombre_yaourt', 'Concombre au yaourt et à la menthe', 10, 4, null, 'entree', '{"printemps","ete"}', '{}', false, false, '{"Coupe le concombre en deux dans la longueur, retire les graines avec une petite cuillère, puis taille-le en fines demi-rondelles.","Sale-le légèrement et laisse-le dégorger 10 min dans une passoire, puis presse-le doucement.","Mélange les yaourts avec l''ail râpé, la menthe ciselée, l''huile, sel et poivre.","Ajoute le concombre et sers bien frais."}');
insert into public.recipe_ingredients (recipe_id, position, ingredient_id, extra_ingredient_ids, label, qty, unit) values ('e_concombre_yaourt', 1, 'legumes', '{}', '1 concombre', 1, null);
