insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('e_tomates_mozza', 'Tomates, mozzarella et basilic', 10, 4, null, 'entree', '{"ete"}', '{}', false, false, '{"Coupe les tomates en rondelles et la mozzarella en tranches fines.","Alterne tomates et mozzarella sur une assiette.","Arrose d''huile et de vinaigre, sale, poivre et ajoute les feuilles de basilic au dernier moment."}');
