insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('e_radis_beurre', 'Radis croquants et fromage frais aux herbes', 10, 4, null, 'entree', '{"printemps"}', '{}', false, false, '{"Lave les radis, coupe les fanes en gardant 1 cm de tige.","Mélange le fromage frais avec la ciboulette ciselée, sel et poivre.","Sers les radis entiers ou coupés en deux avec le fromage aux herbes et une petite tranche de pain grillé."}');
