insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('e_veloute_carotte', 'Petit velouté carotte-orange', 30, 4, null, 'entree', '{"automne","hiver"}', '{}', false, false, '{"Épluche et coupe les carottes en rondelles, émince l''oignon.","Fais revenir l''oignon 3 min dans l''huile, ajoute les carottes, le cumin et le bouillon chaud.","Laisse frémir 20 min jusqu''à ce que les carottes soient tendres.","Mixe avec le jus de l''orange, rectifie sel et poivre. Sers en petits bols."}');
