insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('e_oeuf_mimosa', 'Œufs mimosa au yaourt', 20, 4, null, 'entree', '{"toutes"}', '{}', false, false, '{"Plonge les œufs dans l''eau bouillante 10 min, puis passe-les sous l''eau froide et écale-les.","Coupe-les en deux, retire les jaunes.","Écrase les jaunes avec le yaourt, la moutarde, sel, poivre et ciboulette.","Remplis les blancs, sers sur quelques feuilles de salade."}');
