insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('e_salade_verte', 'Salade verte et vinaigrette légère', 5, 4, null, 'entree', '{"toutes"}', '{}', false, false, '{"Lave et essore bien la salade : une salade mouillée dilue la sauce.","Fouette moutarde, vinaigre, échalote émincée, sel et poivre, puis ajoute l''huile.","Assaisonne au dernier moment."}');
