insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('e_gaspacho', 'Gaspacho express', 15, 4, null, 'entree', '{"ete"}', '{}', false, false, '{"Coupe grossièrement tomates, concombre, poivron et ail.","Mixe le tout longuement avec l''huile, le vinaigre, sel et poivre.","Passe au chinois si tu veux une texture lisse, puis mets au frais au moins 1 h.","Sers bien frais avec quelques feuilles de basilic."}');
