insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('e_soupe_miso_legumes', 'Bouillon de légumes aux herbes', 25, 4, null, 'entree', '{"automne","hiver"}', '{}', false, false, '{"Coupe la carotte en fins bâtonnets, le poireau en rondelles fines, émince les champignons.","Porte le bouillon à frémissement et ajoute les légumes.","Laisse cuire 10 min : les légumes doivent rester un peu croquants.","Sers en bols avec la coriandre ciselée."}');
