insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('d_pommes_four', 'Pommes au four à la cannelle', 30, 4, null, 'dessert', '{"automne","hiver"}', '{}', false, false, '{"Préchauffe le four à 180 °C.","Lave les pommes et retire le trognon avec un vide-pomme ou un petit couteau, sans percer le fond.","Pose-les dans un plat avec l''eau, saupoudre de cannelle et verse un filet de miel au centre.","Enfourne 25 min : elles doivent être fondantes."}');
