insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('d_salade_oranges', 'Oranges à la cannelle', 10, 4, null, 'dessert', '{"hiver"}', '{}', false, false, '{"Pèle les oranges à vif : coupe les deux bouts, puis retire la peau et la partie blanche avec le couteau en suivant l''arrondi.","Coupe-les en fines rondelles et dispose-les sur une assiette avec leur jus.","Saupoudre de cannelle et ajoute quelques feuilles de menthe."}');
