insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('d_compote_maison', 'Compote pommes-poires sans sucre ajouté', 30, 4, null, 'dessert', '{"automne","hiver"}', '{}', false, false, '{"Épluche les fruits, retire les trognons et coupe-les en morceaux.","Mets-les dans une casserole avec l''eau et la cannelle, couvre.","Laisse cuire 20 min à feu doux en remuant de temps en temps.","Écrase à la fourchette ou mixe selon la texture préférée."}');
