insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('d_yaourt_granola', 'Yaourt, banane et flocons d''avoine grillés', 10, 4, null, 'dessert', '{"toutes"}', '{}', false, false, '{"Fais griller les flocons 3 à 4 min à sec dans une poêle, en remuant, jusqu''à ce qu''ils sentent la noisette.","Coupe la banane en rondelles.","Dans chaque bol : yaourt, rondelles de banane, flocons grillés et un trait de miel."}');
