insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('d_mousse_choco_legere', 'Mousse au chocolat légère', 15, 4, null, 'dessert', '{"toutes"}', '{}', false, false, '{"Fais fondre le chocolat au bain-marie ou 1 min au micro-ondes par tranches de 20 s, puis laisse tiédir.","Sépare les blancs des jaunes. Mélange 2 jaunes au chocolat (garde les autres pour une omelette).","Monte les 4 blancs en neige ferme avec la pincée de sel.","Incorpore les blancs au chocolat en 3 fois, en soulevant la masse avec une spatule pour ne pas les casser.","Répartis dans 4 petits verres et laisse prendre 3 h au frais."}');
