insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('d_poires_chocolat', 'Poires pochées, filet de chocolat', 30, 4, null, 'dessert', '{"automne","hiver"}', '{}', false, false, '{"Épluche les poires en gardant la queue.","Porte l''eau à frémissement avec la cannelle et plonge les poires 20 min : la pointe d''un couteau doit entrer facilement.","Égoutte-les. Fais fondre le chocolat et verse un fin filet sur chaque poire."}');
