insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('d_ananas_menthe', 'Carpaccio d''ananas, citron vert et menthe', 10, 4, null, 'dessert', '{"toutes"}', '{}', false, false, '{"Pèle l''ananas, retire les yeux, coupe-le en tranches très fines avec un grand couteau.","Dispose-les en rosace sur une assiette.","Râpe le zeste du citron vert dessus, arrose de son jus et ajoute la menthe ciselée."}');
