insert into public.recipes (id, name, minutes, servings, protein, dish_type, season, tags, is_treat, lunchbox, steps) values ('d_clafoutis_leger', 'Clafoutis léger aux fruits', 45, 4, null, 'dessert', '{"ete"}', '{}', false, false, '{"Préchauffe le four à 180 °C.","Fouette les œufs avec le sucre, ajoute la farine puis le lait petit à petit pour éviter les grumeaux.","Dispose les fruits (cerises, abricots, prunes…) dans un plat à gratin.","Verse la pâte dessus et enfourne 35 min : le dessus doit être doré et la pâte prise."}');
